/* ============ 3D 초기화 ============ */
if(typeof THREE==='undefined'){
  document.getElementById('fallback').style.display='flex';
  throw new Error('three.js not loaded');
}
var CX=500, CZ=250;
function V(x,y,z){return new THREE.Vector3(x-CX, z, y-CZ);} /* scene(x,y,z높이) → three */

var viewport=document.getElementById('viewport');
var canvas=document.getElementById('gl');
var renderer=new THREE.WebGLRenderer({canvas:canvas,antialias:true});
renderer.setPixelRatio(Math.min(Math.max((window.devicePixelRatio||1)*designScale,.75),2.5));
renderer.setClearColor(0xffffff,1);
renderer.outputEncoding=THREE.sRGBEncoding;
var scene=new THREE.Scene();
var camera=new THREE.PerspectiveCamera(33,1,10,9000);
var target=new THREE.Vector3(0,55,0);
var sph={az:-0.62, pol:0.98, dist:1650};       /* 방위각, 극각, 거리 */
var HOME={az:-0.62,pol:0.98,dist:1650,tx:0,ty:55,tz:0};
function updateCam(){
  var sp=Math.sin(sph.pol), cp=Math.cos(sph.pol);
  camera.position.set(
    target.x + sph.dist*sp*Math.sin(sph.az),
    target.y + sph.dist*cp,
    target.z + sph.dist*sp*Math.cos(sph.az));
  camera.lookAt(target);
  if(typeof markCameraMoving==='function')markCameraMoving();
}
scene.add(new THREE.HemisphereLight(0xffffff,0xd8dde2,0.95));
var dir1=new THREE.DirectionalLight(0xffffff,0.55); dir1.position.set(600,900,400); scene.add(dir1);
var dir2=new THREE.DirectionalLight(0xffffff,0.22); dir2.position.set(-500,400,-600); scene.add(dir2);

/* ============ 빌더 ============ */
var groupReg={}, pickables=[], wallsFade=[], flows=[];
function G(term,cat){
  if(term && groupReg[term]) return groupReg[term];
  var g=new THREE.Group(); g.userData={term:term||null,cat:cat||null};
  scene.add(g); if(term)groupReg[term]=g; return g;
}
function dkC(hex){var c=new THREE.Color(hex);c.multiplyScalar(0.9);return c;}
function lam(hex,op){
  var m=new THREE.MeshLambertMaterial({color:new THREE.Color(hex)});
  if(op!==undefined){m.transparent=true;m.opacity=op;}
  m.userData={baseOp:(op===undefined?1:op)};
  return m;
}
function addEdges(g,geo,mesh,hex){
  var ls=new THREE.LineSegments(new THREE.EdgesGeometry(geo),
    new THREE.LineBasicMaterial({color:dkC(hex),transparent:true,opacity:1}));
  ls.material.userData={baseOp:1};
  ls.position.copy(mesh.position); ls.rotation.copy(mesh.rotation);
  ls.userData.isEdge=true; g.add(ls); return ls;
}
function box(g,x,y,z,w,d,h,hex,opt){
  opt=opt||{};
  var geo=new THREE.BoxGeometry(w,h,d);
  var m=new THREE.Mesh(geo,lam(hex,opt.op));
  m.position.set(x+w/2-CX, z+h/2, y+d/2-CZ);
  if(opt.ry)m.rotation.y=opt.ry;
  g.add(m); pickables.push(m);
  if(!opt.noedge)addEdges(g,geo,m,opt.edge||hex);
  return m;
}
function topSurface(g,x,y,z,w,d,hex,op){
  var mat=new THREE.MeshBasicMaterial({color:new THREE.Color(hex),side:THREE.DoubleSide,transparent:op!==undefined,opacity:op===undefined?1:op});
  mat.userData={baseOp:op===undefined?1:op};
  var m=new THREE.Mesh(new THREE.PlaneGeometry(w,d),mat);
  m.rotation.x=-Math.PI/2;m.position.set(x+w/2-CX,z,y+d/2-CZ);
  m.userData.floorTop=true;g.add(m);return m;
}
function gradientGroundSurface(g,x,y,z,w,d,hex){
  var mat=new THREE.ShaderMaterial({
    uniforms:{uColor:{value:new THREE.Color(hex)},uAspect:{value:w/d}},
    vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',
    fragmentShader:'uniform vec3 uColor;uniform float uAspect;varying vec2 vUv;void main(){vec2 p=(vUv-0.5)*vec2(uAspect,1.0);float radius=0.045;vec2 q=abs(p)-(vec2(uAspect*0.5,0.5)-vec2(radius));float sd=length(max(q,0.0))+min(max(q.x,q.y),0.0)-radius;float inset=max(0.0,-sd);float edgeFade=smoothstep(0.0,0.10,inset);gl_FragColor=vec4(uColor,edgeFade*0.54);}',
    transparent:true,depthWrite:false,side:THREE.DoubleSide
  });
  mat.userData={baseOp:1};
  var m=new THREE.Mesh(new THREE.PlaneGeometry(w,d),mat);
  m.rotation.x=-Math.PI/2;m.position.set(x+w/2-CX,z,y+d/2-CZ);
  m.renderOrder=-10;m.userData.floorTop=true;m.userData.groundSurface=true;g.add(m);return m;
}

function cylY(g,x,y,z,r,h,hex,opt){
  opt=opt||{};
  var geo=new THREE.CylinderGeometry(opt.rTop!==undefined?opt.rTop:r, r, h, opt.seg||18);
  var m=new THREE.Mesh(geo,lam(hex,opt.op));
  m.position.set(x-CX, z+h/2, y-CZ);
  g.add(m); pickables.push(m); return m;
}
function cylDir(g,p1,p2,r,hex,opt){ /* p1,p2 = scene coords [x,y,z] */
  opt=opt||{};
  var a=V(p1[0],p1[1],p1[2]), b=V(p2[0],p2[1],p2[2]);
  var d=new THREE.Vector3().subVectors(b,a); var len=d.length();
  var geo=new THREE.CylinderGeometry(r,r,len,opt.seg||10);
  var m=new THREE.Mesh(geo,lam(hex,opt.op));
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), d.normalize());
  g.add(m); if(opt.pick!==false)pickables.push(m);
  return m;
}
function flowTypeFor(hex){
  var c=(hex||'').toUpperCase();
  if(c==='#E2793B'||c==='#EF9D76')return 'heat';
  if(c==='#0FA396'||c==='#57C7BD')return 'tcs';
  if(c==='#EBB410'||c==='#D9A312'||c==='#F0C744')return 'power';
  if(c==='#9CC6E4')return 'condensate';
  if(c==='#3E9CD6'||c==='#42AEE8')return 'chilled';
  return null;
}
function flowTemperaturePalette(key){
  if(key==='condensate')return ['#4E98C5','#86BDD8'];
  if(key==='chilled')return ['#197EB8','#4AACC9'];
  if(key==='tcs')return ['#078A7E','#D47C3E'];
  if(key==='heat')return ['#D87631','#B9472C'];
  return null;
}
function deepenFlowPipeColor(color){
  var hsl={h:0,s:0,l:0};color.getHSL(hsl);
  color.setHSL(hsl.h,Math.min(1,hsl.s*1.06+.015),Math.max(.12,hsl.l*.78));
  return color;
}
function applyTubeGradient(mesh,startHex,endHex,u0,u1){
  var pos=mesh.geometry.attributes.position,count=pos.count,colors=new Float32Array(count*3);
  mesh.geometry.computeBoundingBox();
  var minY=mesh.geometry.boundingBox.min.y,maxY=mesh.geometry.boundingBox.max.y,span=Math.max(.001,maxY-minY);
  var c0=new THREE.Color(startHex),c1=new THREE.Color(endHex),c=new THREE.Color();
  for(var i=0;i<count;i++){
    var local=(pos.getY(i)-minY)/span,u=u0+(u1-u0)*local;
    c.copy(c0).lerp(c1,Math.max(0,Math.min(1,u)));
    colors[i*3]=c.r;colors[i*3+1]=c.g;colors[i*3+2]=c.b;
  }
  mesh.geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));
  mesh.material.vertexColors=true;mesh.material.color.set(0xffffff);
  mesh.material.userData.flowGradient=true;mesh.material.needsUpdate=true;
}
function pipe(g,pts,hex,r,flow){
  r=r||2.2;
  var vs=[],parts=[],key=flowTypeFor(hex);
  for(var i=0;i<pts.length;i++)vs.push(V(pts[i][0],pts[i][1],pts[i][2]));
  var tempPalette=flowTemperaturePalette(key),segmentCount=Math.max(1,pts.length-1);
  for(var j=0;j<pts.length-1;j++){
    var part=cylDir(g,pts[j],pts[j+1],r,hex,{seg:10});
    if(tempPalette)applyTubeGradient(part,tempPalette[0],tempPalette[1],j/segmentCount,(j+1)/segmentCount);
    else if(key)deepenFlowPipeColor(part.material.color);
    part.userData.flowPart=true;parts.push(part);
  }
  for(var k=1;k<pts.length-1;k++){
    var jointColor=tempPalette?new THREE.Color(tempPalette[0]).lerp(new THREE.Color(tempPalette[1]),k/segmentCount):new THREE.Color(hex);
    if(key&&!tempPalette)deepenFlowPipeColor(jointColor);
    var s=new THREE.Mesh(new THREE.SphereGeometry(r*1.12,10,10),lam('#ffffff'));
    s.material.color.copy(jointColor);s.position.copy(vs[k]);s.userData.flowPart=true;g.add(s);parts.push(s);
  }
  if(!key)return;
  var lens=[0],tot=0;
  for(var q=1;q<vs.length;q++){tot+=vs[q].distanceTo(vs[q-1]);lens.push(tot);}
  var dots=[];
  if(flow!==false||key==='tcs'){
    var packetCount=Math.max(4,Math.round(tot/86)),trailOpacity=[1,.62,.34,.14];
    for(var t=0;t<packetCount;t++){
      for(var h=0;h<trailOpacity.length;h++){
        var dotOp=trailOpacity[h];
        var dotMat=new THREE.MeshLambertMaterial({color:new THREE.Color(hex),emissive:new THREE.Color(hex),emissiveIntensity:.55,transparent:true,opacity:dotOp,depthWrite:false,depthTest:false});
        dotMat.userData={baseOp:dotOp,flowBaseColor:new THREE.Color(hex)};
        var dotSize=Math.max(1.35,r*(.92-h*.08));
        var dm=new THREE.Mesh(new THREE.SphereGeometry(dotSize,10,10),dotMat);
        dm.renderOrder=30;dm.userData.flowPart=true;dm.userData.flowParticle=true;dm.userData.flowU=t/packetCount-h*.0085;g.add(dm);dots.push(dm);
      }
    }
  }
  flows.push({vs:vs,lens:lens,tot:tot,dots:dots,parts:parts,key:key,off:Math.random(),enabled:true});
}
function fanTop(g,x,y,z,r,hexRing){ /* 상향 팬 */
  cylY(g,x,y,z,r+1.4,2.4,hexRing||'#8A8577',{seg:20});
  cylY(g,x,y,z+1.2,r*0.92,1.2,'#F3F4F6',{seg:20});
  var b1=box(g,x-r*0.85,y-1.4,z+2.2,r*1.7,2.8,1.1,'#6B7280',{noedge:true});
  b1.rotation.y=0.5;
  var b2=box(g,x-r*0.85,y-1.4,z+2.2,r*1.7,2.8,1.1,'#6B7280',{noedge:true});
  b2.rotation.y=-1.05;
  cylY(g,x,y,z+2.0,1.6,2.2,'#4B5563',{seg:10});
}
function fanFront(g,x,y,z,r,axis){ /* 수직면 팬: axis 'z'=남북면, 'x'=동서면 */
  var ring=new THREE.Mesh(new THREE.CylinderGeometry(r+1.2,r+1.2,2.2,20),lam('#5B7B95'));
  var disc=new THREE.Mesh(new THREE.CylinderGeometry(r*0.9,r*0.9,1.1,20),lam('#EDF1F5'));
  var hub=new THREE.Mesh(new THREE.CylinderGeometry(1.5,1.5,2.6,10),lam('#41586C'));
  var bl1=new THREE.Mesh(new THREE.BoxGeometry(r*1.65,1.4,2.4),lam('#41586C'));
  var bl2=bl1.clone(); bl2.material=lam('#41586C');
  var grp=[ring,disc,hub,bl1,bl2];
  for(var i=0;i<grp.length;i++){
    var m=grp[i];
    if(axis==='z'){m.rotation.x=Math.PI/2;}else{m.rotation.z=Math.PI/2;}
    m.position.copy(V(x,y,z)); g.add(m);
  }
  bl1.rotateOnWorldAxis? null:null;
  if(axis==='z'){bl1.rotation.y=0.6;bl2.rotation.y=-0.9;}else{bl1.rotation.x=0.6;bl2.rotation.x=-0.9;}
}
function ladder(g,x,y,z,h,hex){
  hex=hex||'#9AA3AD';
  box(g,x-2.4,y,z,1.1,1.1,h,hex,{noedge:true});
  box(g,x+1.3,y,z,1.1,1.1,h,hex,{noedge:true});
  for(var i=1;i<h/9;i++)box(g,x-2.4,y,z+i*9,4.8,1.0,1.0,hex,{noedge:true});
}
function wall(x,y,z,w,d,h,nx,nz,interior){
  var g=G(null,null);
  var hex='#EDEFF2';
  var geo=new THREE.BoxGeometry(w,h,d);
  var m=new THREE.Mesh(geo,lam(hex, interior?0.45:0.95));
  m.material.depthWrite=!interior;
  m.position.set(x+w/2-CX, z+h/2, y+d/2-CZ);
  g.add(m);
  var edgeColor=interior?'#DEE2E5':'#C5CBD0';
  var e=new THREE.LineSegments(new THREE.EdgesGeometry(geo),new THREE.LineBasicMaterial({color:new THREE.Color(edgeColor),transparent:true,opacity:interior?.58:.78,depthTest:true,depthWrite:false}));
  e.material.userData={baseOp:interior?.58:.78};e.position.copy(m.position);e.userData.isEdge=true;g.add(e);
  if(!interior)wallsFade.push({m:m,e:e,n:new THREE.Vector3(nx,0,nz)});
  return m;
}
/* ============ 팔레트 ============ */
var P={
  ground:'#DDE1E4', slab:'#D3D8DC', roof:'#D9DEE2', groundTop:'#EAECED', slabTop:'#E8EAEC', roofTop:'#E9EBED', hall:'#DEE4E9', plant:'#ECECE8', office:'#EFEDEA',
  cream:'#F0EBE1', cream2:'#E7E0D2',
  rackBody:'#3F2A34', rackDoor:'#5C3B49', tray:'#93AF7B',
  blue:'#A9BFD3', blueD:'#7E9DB8', cdu:'#7FA7D8', teal:'#8FD0C2',
  yel:'#EDBE4B', yelD:'#D9A32E', purp:'#ACA2DA',
  gray:'#CBD1D7', steel:'#B9C2CA', wood:'#C8A87E', rose:'#D8ACA2'
};

