/* ============ 라벨 (방사형 자동 배치) ============ */
/* BASE EQUIPMENT COLOR CLARITY: boost only equipment meshes; selection desaturation remains unchanged */
(function enhanceBaseEquipmentColors(){
  var seen=[];
  for(var id in groupReg)groupReg[id].traverse(function(o){
    if(!o.isMesh||!o.material||!o.material.color||o.userData.flowPart||o.userData.selectionOutline)return;
    if(seen.indexOf(o.material)!==-1)return;seen.push(o.material);
    var hsl={h:0,s:0,l:0};o.material.color.getHSL(hsl);
    if(hsl.s>.04)hsl.s=Math.min(1,hsl.s*1.20);
    hsl.l=Math.max(.08,hsl.l-(hsl.l>.78?.095:.065));
    o.material.color.setHSL(hsl.h,hsl.s,hsl.l);
  });
})();
/* FLOW EQUIPMENT COLOR EMPHASIS: deepen only equipment connected to visible flow systems. */
(function emphasizeFlowEquipment(){
  var flowEquipment=['cooling-tower','dry-cooler','chiller','pumps','water-treatment','tes','crah','fws','containment','tcs','manifold','cold-plate','cdu','switchgear','ups','battery','busway','pdu','transformer','generator','gpu-rack'];
  var seen=[];
  for(var i=0;i<flowEquipment.length;i++){
    var g=groupReg[flowEquipment[i]];if(!g)continue;
    g.traverse(function(o){
      if(!o.isMesh||!o.material||!o.material.color||o.userData.flowPart||o.userData.selectionOutline||o.userData.floorTop)return;
      if(seen.indexOf(o.material)!==-1)return;seen.push(o.material);
      var hsl={h:0,s:0,l:0};o.material.color.getHSL(hsl);
      if(hsl.s>.025)hsl.s=Math.min(1,hsl.s*1.18+.018);
      hsl.l=Math.max(.08,hsl.l-(hsl.l>.72?.085:(hsl.l>.42?.055:.025)));
      o.material.color.setHSL(hsl.h,hsl.s,hsl.l);
      o.material.userData=o.material.userData||{};o.material.userData.flowEquipment=true;
    });
  }
})();
