  function cross(o,a,b){return (a.x-o.x)*(b.y-o.y)-(a.y-o.y)*(b.x-o.x);}
  var lower=[],upper=[];
  for(var i=0;i<points.length;i++){while(lower.length>=2&&cross(lower[lower.length-2],lower[lower.length-1],points[i])<=0)lower.pop();lower.push(points[i]);}
  for(var j=points.length-1;j>=0;j--){while(upper.length>=2&&cross(upper[upper.length-2],upper[upper.length-1],points[j])<=0)upper.pop();upper.push(points[j]);}
